mapper.select:
select id, from_user, to_user, status, created_at, updated_at
from t_friend_request
where id = #{id,jdbcType=BIGINT}

select id, from_user, to_user, status, created_at, updated_at
from t_friend_request
where from_user = #{fromUser,jdbcType=VARCHAR}
  and to_user = #{toUser,jdbcType=VARCHAR}
limit 1

mapper.update:
update t_friend_request
set status = 0, updated_at = #{updatedAt,jdbcType=BIGINT}
where id = #{id,jdbcType=BIGINT}
  and status <> 0

update t_friend_request
set status = #{status,jdbcType=TINYINT}, updated_at = #{updatedAt,jdbcType=BIGINT}
where id = #{id,jdbcType=BIGINT}
  and status = 0
